function toutesLesRecettes(syn) {
  return { reverb: syn.reverb(), tissage: syn.tissage(), lancer: syn.lancer(), point: [syn.point(1), syn.point(2)], eclosion: syn.eclosion(), tension: syn.tension(), battement: [syn.battement(1), syn.battement(2)], avant: syn.avant(), floraison: syn.floraison(), spores: syn.spores(), cloture: syn.cloture(), ambiance: syn.ambiance() };
}
